use super::*;
fn observed<R>(f:impl FnOnce()->R)->(R,(usize,usize)){semio_framework_value_testing_allocator::observe_retirement_allocations(f)}
struct Bank{g:RetainedCloneGrant,fuel:u64}
impl Bank{fn new(f:&serde_json::Value)->Self{Self{g:RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize},fuel:f["fuel"].as_u64().unwrap()}}fn loan(&self,d:crate::RetirementDemand)->RetainedCloneGrant{assert!(self.fuel>0&&crate::retained_clone::retained_clone_grant_admits(self.g,d));RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}fn post(&mut self,turn:crate::RetainedWorkOutcome,heap:(usize,usize))->Result<RetainedCloneStep,ValueError>{let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};assert!(p.fits(self.g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.g.maximum_items-=p.copied_items;self.g.maximum_copy_bytes-=p.copied_bytes;self.g.maximum_capacity_bytes-=p.retained_capacity_bytes;self.g.maximum_release_bytes-=p.released_bytes;self.fuel=self.fuel.checked_sub(turn.work).unwrap();turn.result}}
fn finish(mut append:PagedUtf8AppendCursor,value:PagedUtf8<8192>,bank:&mut Bank,max:u64){append.begin_close();for _ in 0..max{if append.terminal_is_empty(){break}let g=bank.loan(append.next_demand(4096).unwrap());let(turn,heap)=observed(||append.close_step(g));let step=bank.post(turn,heap).unwrap();if matches!(step,RetainedCloneStep::Complete(_)){assert!(append.terminal_is_empty());}}assert!(append.terminal_is_empty());assert_eq!(observed(||drop(append)).1,(0,0));let mut close=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..max{if close.terminal_is_empty(){break}let g=bank.loan(close.next_demand(4096).unwrap());let(result,heap)=observed(||close.step(g));let work=close.last_turn_work();bank.post(crate::RetainedWorkOutcome{result,work},heap).unwrap();}assert!(close.terminal_is_empty());}
#[test]fn actual_append_normal_uses_real_work_with_partial_utf8_and_original_stock_through_close(){let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();assert_eq!(PAGED_UTF8_CHUNK_BYTES,f["chunkBytes"].as_u64().unwrap()as usize);for text in f["texts"].as_array().unwrap(){let source=text.as_str().unwrap().to_owned();for body in f["bodies"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;for cut in f["cancelCuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap())).chain([None]){let mut bank=Bank::new(&f["stock"]);let mut value=PagedUtf8::<8192>::new();let(mut append,heap)=observed(PagedUtf8AppendCursor::default);assert_eq!(heap,(0,0));let mut refused=false;for index in 0..f["stock"]["maximumTurns"].as_u64().unwrap(){if cut==Some(index)||append.complete{break}let d=append.next_advance_demand(&source,&value,body).unwrap();let g=bank.loan(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let(turn,heap)=observed(||append.advance(&source,&mut value,body,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(append.next_advance_demand(&source,&value,body).unwrap(),d);}if d.capacity_bytes>0&&!refused{let((turn,attempts),heap)=observed(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||append.advance(&source,&mut value,body,g)));assert_eq!(attempts,1);assert_eq!(turn.work,1);assert!(bank.post(turn,heap).is_err());refused=true;continue}let(turn,heap)=observed(||append.advance(&source,&mut value,body,g));assert!(turn.work<=1);bank.post(turn,heap).unwrap();}if cut.is_none(){assert!(append.complete);assert_eq!(serde_json::to_value(value.to_string()).unwrap(),serde_json::to_value(&source).unwrap());let(turn,heap)=observed(||append.advance(&source,&mut value,body,Default::default()));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}finish(append,value,&mut bank,f["stock"]["maximumTurns"].as_u64().unwrap());}}}}
#[test]fn actual_append_rejects_changed_source_utf8_before_publishing_and_caches_only_the_real_fault(){let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut bank=Bank::new(&f["stock"]);let mut source=f["changedSource"]["before"].as_str().unwrap().to_owned();let pointer=source.as_ptr();let mut value=PagedUtf8::<8192>::new();let mut append=PagedUtf8AppendCursor::default();for _ in 0..10000{if append.position==1{break}let g=bank.loan(append.next_advance_demand(&source,&value,1).unwrap());let(turn,heap)=observed(||append.advance(&source,&mut value,1,g));bank.post(turn,heap).unwrap();}assert_eq!(append.position,1);source.replace_range(..,f["changedSource"]["after"].as_str().unwrap());assert_eq!(source.as_ptr(),pointer);let mut faulted=false;for _ in 0..10000{let g=bank.loan(append.next_advance_demand(&source,&value,1).unwrap());let(turn,heap)=observed(||append.advance(&source,&mut value,1,g));let work=turn.work;match bank.post(turn,heap){Ok(_)=>{},Err(error)=>{assert_eq!(work,1);assert_eq!(error.message.as_ref(),f["changedSource"]["failure"].as_str().unwrap());faulted=true;break;}}}assert!(faulted);assert!(!append.complete);assert!(value.is_empty());let(turn,heap)=observed(||append.advance(&source,&mut value,1,Default::default()));assert_eq!(turn.work,0);assert!(turn.result.is_err());assert_eq!(heap,(0,0));finish(append,value,&mut bank,f["stock"]["maximumTurns"].as_u64().unwrap());}
